Value.Calculation:
JSONSetElement ( "{}" ;
	[ "tip" ; "Nivelacija" ; JSONString ] ;
	[ "naslov" ; "Nivelacija cijena" ; JSONString ] ;
	[ "broj" ; $broj ; JSONString ] ;
	[ "datum" ; Year ( $datum ) & "-" & Right ( "0" & Month ( $datum ) ; 2 ) & "-" & Right ( "0" & Day ( $datum ) ; 2 ) ; JSONString ] ;
	[ "datumPrikaz" ; Right ( "0" & Day ( $datum ) ; 2 ) & "." & Right ( "0" & Month ( $datum ) ; 2 ) & "." & Year ( $datum ) ; JSONString ] ;
	[ "status" ; epSQLResult ( 0 ; 2 ; "rs_hdr" ) ; JSONString ] ;
	[ "datumKnjizenja" ; epSQLResult ( 0 ; 3 ; "rs_hdr" ) ; JSONString ] ;
	[ "nacinIzmjene" ; epSQLResult ( 0 ; 4 ; "rs_hdr" ) ; JSONString ] ;
	[ "napomena" ; epSQLResult ( 0 ; 5 ; "rs_hdr" ) ; JSONString ] ;
	[ "datumIspisa" ; Right ( "0" & Day ( Get ( CurrentDate ) ) ; 2 ) & "." & Right ( "0" & Month ( Get ( CurrentDate ) ) ; 2 ) & "." & Year ( Get ( CurrentDate ) ) ; JSONString ]
)

JSONSetElement ( "{}" ;
	[ "ranijaVrijednost" ; GetAsNumber ( epSQLResult ( 0 ; 10 ; "rs_hdr" ) ) ; JSONNumber ] ;
	[ "novaVrijednost" ; GetAsNumber ( epSQLResult ( 0 ; 11 ; "rs_hdr" ) ) ; JSONNumber ] ;
	[ "efekat" ; GetAsNumber ( epSQLResult ( 0 ; 12 ; "rs_hdr" ) ) ; JSONNumber ] ;
	[ "ranijaVrijednostBruto" ; GetAsNumber ( epSQLResult ( 0 ; 7 ; "rs_hdr" ) ) ; JSONNumber ] ;
	[ "novaVrijednostBruto" ; GetAsNumber ( epSQLResult ( 0 ; 8 ; "rs_hdr" ) ) ; JSONNumber ] ;
	[ "efekatBruto" ; GetAsNumber ( epSQLResult ( 0 ; 9 ; "rs_hdr" ) ) ; JSONNumber ] ;
	[ "razlikaRUC" ; GetAsNumber ( epSQLResult ( 0 ; 12 ; "rs_hdr" ) ) ; JSONNumber ] ;
	[ "razlikaPDV" ; GetAsNumber ( epSQLResult ( 0 ; 13 ; "rs_hdr" ) ) ; JSONNumber ]
)

epSQLExecute (
	"SELECT Company.CompanyName, Company.Address, Company.City, Company.PostalCode," &
	"  Company.JIB, Company.PDVBroj, Company.Phone, Company.Email" &
	" FROM Company WHERE Company.PrimaryKey = ?" ;
	"useSQLResult=rs_co" ;
	$companyId
)

If ( not IsEmpty ( $err ) or epSQLResultRowCount ( "rs_co" ) = 0 ;
	"{}" ;
	JSONSetElement ( "{}" ;
		[ "naziv" ; epSQLResult ( 0 ; 0 ; "rs_co" ) ; JSONString ] ;
		[ "adresa" ; epSQLResult ( 0 ; 1 ; "rs_co" ) ; JSONString ] ;
		[ "grad" ; epSQLResult ( 0 ; 2 ; "rs_co" ) ; JSONString ] ;
		[ "postanskiBroj" ; epSQLResult ( 0 ; 3 ; "rs_co" ) ; JSONString ] ;
		[ "jib" ; epSQLResult ( 0 ; 4 ; "rs_co" ) ; JSONString ] ;
		[ "pdvBroj" ; epSQLResult ( 0 ; 5 ; "rs_co" ) ; JSONString ] ;
		[ "telefon" ; epSQLResult ( 0 ; 6 ; "rs_co" ) ; JSONString ] ;
		[ "email" ; epSQLResult ( 0 ; 7 ; "rs_co" ) ; JSONString ]
	)
)

JSONSetElement ( $stavke ; "[" & $i & "]" ;
	JSONSetElement ( "{}" ;
		[ "redniBroj" ; GetAsNumber ( epSQLResult ( $i ; 0 ; "rs_lines" ) ) ; JSONNumber ] ;
		[ "sifra" ; epSQLResult ( $i ; 1 ; "rs_lines" ) ; JSONString ] ;
		[ "naziv" ; epSQLResult ( $i ; 2 ; "rs_lines" ) ; JSONString ] ;
		[ "jm" ; epSQLResult ( $i ; 3 ; "rs_lines" ) ; JSONString ] ;
		[ "kolicina" ; GetAsNumber ( epSQLResult ( $i ; 4 ; "rs_lines" ) ) ; JSONNumber ] ;
		[ "staraCijena" ; GetAsNumber ( epSQLResult ( $i ; 5 ; "rs_lines" ) ) ; JSONNumber ] ;
		[ "ranijaVrijednost" ; GetAsNumber ( epSQLResult ( $i ; 6 ; "rs_lines" ) ) ; JSONNumber ] ;
		[ "novaCijena" ; GetAsNumber ( epSQLResult ( $i ; 7 ; "rs_lines" ) ) ; JSONNumber ] ;
		[ "novaVrijednost" ; GetAsNumber ( epSQLResult ( $i ; 8 ; "rs_lines" ) ) ; JSONNumber ] ;
		[ "efekat" ; GetAsNumber ( epSQLResult ( $i ; 9 ; "rs_lines" ) ) ; JSONNumber ] ;
		[ "staraCijenaBruto" ; GetAsNumber ( epSQLResult ( $i ; 10 ; "rs_lines" ) ) ; JSONNumber ] ;
		[ "ranijaVrijednostBruto" ; GetAsNumber ( epSQLResult ( $i ; 11 ; "rs_lines" ) ) ; JSONNumber ] ;
		[ "novaCijenaBruto" ; GetAsNumber ( epSQLResult ( $i ; 12 ; "rs_lines" ) ) ; JSONNumber ] ;
		[ "novaVrijednostBruto" ; GetAsNumber ( epSQLResult ( $i ; 13 ; "rs_lines" ) ) ; JSONNumber ] ;
		[ "efekatBruto" ; GetAsNumber ( epSQLResult ( $i ; 14 ; "rs_lines" ) ) ; JSONNumber ] ;
		[ "razlikaPDV" ; GetAsNumber ( epSQLResult ( $i ; 15 ; "rs_lines" ) ) ; JSONNumber ] ;
		[ "stariPDVPostotak" ; GetAsNumber ( epSQLResult ( $i ; 16 ; "rs_lines" ) ) ; JSONNumber ] ;
		[ "noviPDVPostotak" ; GetAsNumber ( epSQLResult ( $i ; 17 ; "rs_lines" ) ) ; JSONNumber ] ;
		[ "nabavnaCijena" ; GetAsNumber ( epSQLResult ( $i ; 18 ; "rs_lines" ) ) ; JSONNumber ] ;
		[ "stariRUC" ; GetAsNumber ( epSQLResult ( $i ; 19 ; "rs_lines" ) ) ; JSONNumber ] ;
		[ "noviRUC" ; GetAsNumber ( epSQLResult ( $i ; 20 ; "rs_lines" ) ) ; JSONNumber ] ;
		[ "batchId" ; epSQLResult ( $i ; 21 ; "rs_lines" ) ; JSONString ] ;
		[ "nacinIzmjene" ; epSQLResult ( $i ; 22 ; "rs_lines" ) ; JSONString ]
	) ;
	JSONObject
)

JSONSetElement ( "{}" ;
	[ "verzija" ; 1 ; JSONNumber ] ;
	[ "document" ; $doc ; JSONObject ] ;
	[ "company" ; $company ; JSONObject ] ;
	[ "stavke" ; $stavke ; JSONArray ] ;
	[ "rekapitulacija" ; $rekap ; JSONObject ]
)
